export type { ModelInspection } from "./model-inspection";
export { useModelViewer, useModelViewerCamera } from "./model-viewer-context";
export {
  ModelViewerFullscreen,
  ModelViewerOverlay,
  ModelViewerStatus,
} from "./model-viewer-core-parts";
export { ModelViewerRoot } from "./model-viewer-root";
export { ModelViewerScene } from "./model-viewer-scene";
export type { ModelViewerSkeletonProps } from "./model-viewer-skeleton";
export { ModelViewerSkeleton } from "./model-viewer-skeleton";
export type {
  ModelViewerRootProps,
  ModelViewerState,
  ViewerCameraPreset,
  ViewerCameraState,
  ViewerLighting,
  ViewerMode,
  ViewerShading,
} from "./model-viewer-types";
export { ViewCube } from "./view-cube";

import type { ModelInspection } from "./model-inspection";

type Node = ModelInspection["nodes"][number];
const parentPath = (id: string) => id.slice(0, Math.max(0, id.lastIndexOf("/")));

/** Index parent paths once; searches walk each matching ancestor at most once. */
export function indexHierarchy(nodes: Node[]) {
  const parents = new Map<string, string>();
  const branches = new Set<string>();
  const names = new Map<string, string>();
  for (const node of nodes) {
    const parent = parentPath(node.id);
    parents.set(node.id, parent);
    branches.add(parent);
    names.set(node.id, node.name.toLowerCase());
  }
  return {
    branches,
    visible(query: string, collapsed: ReadonlySet<string>): Node[] {
      const normalized = query.toLowerCase();
      if (normalized) {
        const matching = new Set<string>();
        for (const node of nodes) {
          if (!names.get(node.id)!.includes(normalized)) continue;
          let id: string | undefined = node.id;
          while (id && !matching.has(id)) {
            matching.add(id);
            id = parents.get(id) ?? parentPath(id);
          }
        }
        return nodes.filter((node) => matching.has(node.id));
      }
      // Memoize hidden ancestry; standalone consumers need not sort parents
      // before children, and collapsed paths may refer to omitted groups.
      const hidden = new Map<string, boolean>();
      return nodes.filter((node) => {
        const chain: string[] = [];
        let id = node.id;
        let result = false;
        while (id) {
          if (hidden.has(id)) {
            result = hidden.get(id)!;
            break;
          }
          chain.push(id);
          const parent = parents.get(id) ?? parentPath(id);
          if (collapsed.has(parent)) {
            result = true;
            break;
          }
          id = parent;
        }
        for (const child of chain) hidden.set(child, result);
        return !result;
      });
    },
  };
}

export type { ModelInspectorProps } from "./model-inspector";
export { ModelInspector } from "./model-inspector";
export type { ModelViewerInspectorProps } from "./model-viewer-inspector";
export { ModelViewerInspector } from "./model-viewer-inspector";

import {
  type AnimationClip,
  AnimationMixer,
  Box3,
  type Material,
  Matrix4,
  type Mesh,
  type Object3D,
  type OrthographicCamera,
  Sphere,
  type Texture,
  Vector3,
} from "three";
import { clone } from "three/addons/utils/SkeletonUtils.js";

const sampled = new WeakSet<Object3D>();

/** Cache a conservative sampled envelope without changing the loader's shared pose. */
export function prepareAnimationBounds(root: Object3D, clips: AnimationClip[]) {
  if (sampled.has(root) || clips.length === 0) return;
  sampled.add(root);
  root.updateMatrixWorld(true);
  const copy = clone(root);
  copy.updateMatrixWorld(true);
  const mixer = new AnimationMixer(copy);
  const box = new Box3().setFromObject(copy, true);
  for (const clip of clips) {
    const action = mixer.clipAction(clip).play();
    for (let sample = 0; sample <= 16; sample++) {
      mixer.setTime((clip.duration * sample) / 16);
      copy.updateMatrixWorld(true);
      box.union(new Box3().setFromObject(copy, true));
    }
    action.stop();
  }
  mixer.stopAllAction();
  mixer.uncacheRoot(copy);
  copy.updateMatrixWorld(true);
  box.applyMatrix4(copy.matrixWorld.clone().invert());
  root.userData.viewerAnimationBounds = [box.min.toArray(), box.max.toArray()];
}

export type ModelInspection = {
  dimensions: [number, number, number];
  triangles: number;
  materials: number;
  textures: number;
  nodes: { id: string; name: string; type: string; depth: number; mesh: boolean }[];
};

export function inspectModel(root: Object3D): ModelInspection {
  root.updateWorldMatrix(true, true);
  const materials = new Set<Material>();
  const textures = new Set<Texture>();
  let triangles = 0;
  const nodes: ModelInspection["nodes"] = [];
  function visit(object: Object3D, path: string, depth: number) {
    if (object.userData.viewerHelper) return;
    object.userData.viewerNodeId = path;
    const mesh = object as Mesh;
    nodes.push({
      id: path,
      name: object.name || object.type,
      type: object.type,
      depth,
      mesh: Boolean(mesh.isMesh),
    });
    if (mesh.isMesh) {
      triangles +=
        ((mesh.geometry.index?.count ?? mesh.geometry.attributes.position?.count ?? 0) / 3) *
        ((mesh as Mesh & { count?: number }).count ?? 1);
      for (const material of Array.isArray(mesh.material) ? mesh.material : [mesh.material]) {
        materials.add(material);
        for (const value of Object.values(material)) if (value?.isTexture) textures.add(value);
      }
    }
    object.children.forEach((child, index) => visit(child, `${path}/${index}`, depth + 1));
  }
  visit(root, "0", 0);
  return {
    dimensions: new Box3().setFromObject(root, true).getSize(new Vector3()).toArray(),
    triangles: Math.round(triangles),
    materials: materials.size,
    textures: textures.size,
    nodes,
  };
}

export function frameBounds(object: Object3D, aspect: number, fov = 42) {
  object.updateWorldMatrix(true, true);
  const box = new Box3().setFromObject(object, true);
  object.traverse((node) => {
    const bounds = node.userData.viewerAnimationBounds as [number[], number[]] | undefined;
    if (bounds)
      box.union(
        new Box3(
          new Vector3().fromArray(bounds[0]),
          new Vector3().fromArray(bounds[1]),
        ).applyMatrix4(node.matrixWorld),
      );
  });
  const sphere = box.getBoundingSphere(new Sphere());
  const radius = Number.isFinite(sphere.radius) && sphere.radius > 0 ? sphere.radius : 0.001;
  const center = box.isEmpty() ? new Vector3() : sphere.center;
  const halfFov = (fov * Math.PI) / 360;
  const limitingAngle = Math.min(halfFov, Math.atan(Math.tan(halfFov) * Math.max(aspect, 0.001)));
  const distance = (radius / Math.sin(limitingAngle)) * 1.15;
  return {
    box,
    center,
    radius,
    distance,
    near: Math.max(radius / 1000, 1e-8),
    far: distance + radius * 100,
  };
}

/** Fit the bounds projected onto the camera plane, independent of their depth. */
export function orthographicZoom(box: Box3, camera: OrthographicCamera, direction: Vector3) {
  const basis = new Matrix4().lookAt(direction, new Vector3(), camera.up);
  const right = new Vector3().setFromMatrixColumn(basis, 0);
  const up = new Vector3().setFromMatrixColumn(basis, 1);
  const projected = new Box3();
  if (!box.isEmpty()) {
    for (const x of [box.min.x, box.max.x])
      for (const y of [box.min.y, box.max.y])
        for (const z of [box.min.z, box.max.z]) {
          const corner = new Vector3(x, y, z);
          projected.expandByPoint(new Vector3(corner.dot(right), corner.dot(up), 0));
        }
  }
  const size = projected.getSize(new Vector3());
  const minimum = (Math.max(size.x, size.y) || 0.001) * 1e-6;
  return Math.min(
    (camera.right - camera.left) / (Math.max(size.x, minimum) * 1.15),
    (camera.top - camera.bottom) / (Math.max(size.y, minimum) * 1.15),
  );
}

"use client";

import {
  Box,
  ChevronDown,
  ChevronRight,
  Crosshair,
  Image,
  Layers,
  Search,
  Triangle,
  X,
} from "lucide-react";
import { type ComponentProps, useId, useMemo, useState } from "react";
import { TooltipProvider } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";
import { indexHierarchy } from "./inspector-hierarchy";
import type { ModelInspection } from "./model-inspection";
import type { ModelInspectorPosition } from "./model-viewer-types";
import { ViewerControlButton as Button } from "./viewer-ui";
import "./model-viewer.css";

export type ModelInspectorProps = ComponentProps<"aside"> & {
  inspection: ModelInspection;
  selectedMesh?: string | null;
  onSelectMesh: (id: string | null) => void;
  onClose?: () => void;
  /** Side of the viewer used by the positioned inspector. Defaults to right. */
  position?: ModelInspectorPosition;
  className?: string;
};

export function ModelInspector({
  inspection,
  selectedMesh,
  onSelectMesh,
  onClose,
  position = "right",
  className,
  ...props
}: ModelInspectorProps) {
  const [query, setQuery] = useState("");
  const [collapsed, setCollapsed] = useState<Set<string>>(() => new Set());
  const heading = useId();
  const selected = inspection.nodes.find((node) => node.id === selectedMesh);
  const hierarchy = useMemo(() => indexHierarchy(inspection.nodes), [inspection.nodes]);
  const visible = useMemo(() => hierarchy.visible(query, collapsed), [hierarchy, query, collapsed]);
  const [page, setPage] = useState({ nodes: inspection.nodes, query, limit: 200 });
  const limit = page.nodes === inspection.nodes && page.query === query ? page.limit : 200;
  function changeQuery(next: string) {
    setQuery(next);
    setPage({ nodes: inspection.nodes, query: next, limit: 200 });
  }
  function toggle(id: string) {
    setCollapsed((current) => {
      const next = new Set(current);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }

  return (
    <TooltipProvider delay={350}>
      <aside
        data-slot="model-inspector"
        data-position={position}
        className={cn(
          "viewer-inspector flex flex-col overflow-x-hidden overflow-y-auto rounded-(--radius) border bg-popover text-[11px] text-popover-foreground shadow-md [scrollbar-width:thin] [&>*:not(ul)]:shrink-0",
          className,
        )}
        aria-labelledby={heading}
        {...props}
      >
        <header className="inspector-header flex items-center gap-2.5 border-b px-4 py-[15px] @max-[680px]/viewer:px-3 @max-[680px]/viewer:py-2.5">
          <span className="inspector-emblem grid size-[35px] place-items-center rounded-[calc(var(--radius)-2px)] border bg-secondary text-primary">
            <Box size={18} />
          </span>
          <div>
            <span className="inspector-eyebrow text-[9px] font-semibold tracking-[0.12em] text-muted-foreground uppercase">
              Scene overview
            </span>
            <h3 id={heading} className="mt-0.5 text-sm font-[650] tracking-[-0.02em]">
              Model inspector
            </h3>
          </div>
          {onClose && (
            <Button
              className="ml-auto"
              variant="ghost"
              size="icon-sm"
              aria-label="Close inspector"
              onClick={onClose}
            >
              <X size={16} />
            </Button>
          )}
        </header>
        <div className="inspector-metrics mx-3.5 my-[13px] grid grid-cols-3 gap-1.5 @max-[680px]/viewer:mx-3 @max-[680px]/viewer:my-[9px]">
          {[
            { label: "Triangles", value: inspection.triangles, Icon: Triangle },
            { label: "Materials", value: inspection.materials, Icon: Layers },
            { label: "Textures", value: inspection.textures, Icon: Image },
          ].map(({ label, value, Icon }) => (
            <div
              key={label}
              className="grid gap-1 rounded-[calc(var(--radius)-2px)] border bg-muted/40 p-2.5 @max-[680px]/viewer:gap-0.5 @max-[680px]/viewer:p-[7px]"
            >
              <Icon size={14} className="text-muted-foreground @max-[680px]/viewer:hidden" />
              <strong className="text-lg font-[650] tracking-[-0.04em] tabular-nums">
                {value.toLocaleString()}
              </strong>
              <span className="text-[9px] text-muted-foreground">{label}</span>
            </div>
          ))}
        </div>
        <section
          className="inspector-dimensions mx-3.5 mb-3.5 @max-[680px]/viewer:mx-3 @max-[680px]/viewer:mb-[9px]"
          aria-label="Dimensions"
        >
          <div className="inspector-section-label flex justify-between text-[10px] font-[650]">
            Dimensions{" "}
            <span className="text-[9px] font-normal text-muted-foreground">model units</span>
          </div>
          <div className="inspector-axis-values mt-[7px] grid grid-cols-3 gap-1.5">
            {inspection.dimensions.map((value, index) => (
              <div
                key={["X", "Y", "Z"][index]}
                className="flex items-center gap-[7px] rounded-md border px-2 py-1.5"
              >
                <span
                  data-axis={index}
                  className="text-[9px] font-[750] data-[axis=0]:text-[#b85b63] data-[axis=1]:text-[#58855c] data-[axis=2]:text-[#527da9]"
                >
                  {["X", "Y", "Z"][index]}
                </span>
                <strong className="font-mono text-[10px] font-medium wrap-anywhere">
                  {Number(value.toPrecision(4))}
                </strong>
              </div>
            ))}
          </div>
        </section>
        <div className="inspector-hierarchy-heading flex justify-between border-t px-4 pt-3 pb-2 @max-[680px]/viewer:px-3 @max-[680px]/viewer:pt-2 @max-[680px]/viewer:pb-1.5">
          <span className="inspector-section-label flex justify-between text-[10px] font-[650]">
            Hierarchy
          </span>
          <span className="text-[9px] text-muted-foreground">
            {inspection.nodes.filter((node) => node.mesh).length} meshes
          </span>
        </div>
        <label className="inspector-search mx-3.5 mb-2 flex items-center gap-2 rounded-[7px] border px-[9px] py-1.5 text-muted-foreground focus-within:outline-2 focus-within:outline-offset-2 focus-within:outline-ring">
          <Search size={14} />
          <input
            className="min-w-0 w-full bg-transparent text-[11px] text-foreground outline-none"
            aria-label="Search hierarchy"
            placeholder="Find an object…"
            value={query}
            onChange={(event) => changeQuery(event.target.value)}
          />
          {query && (
            <Button
              size="icon-sm"
              variant="ghost"
              aria-label="Clear search"
              onClick={() => changeQuery("")}
            >
              <X size={12} />
            </Button>
          )}
        </label>
        <ul
          className="inspector-tree m-0 min-h-[60px] flex-1 list-none overflow-y-auto px-2.5 pb-2.5 [scrollbar-width:thin]"
          aria-label="Scene hierarchy"
        >
          {visible.slice(0, limit).map((node) => {
            const hasChildren = hierarchy.branches.has(node.id);
            return (
              <li
                data-slot="model-inspector-node"
                data-state={selectedMesh === node.id ? "selected" : undefined}
                key={node.id}
                style={{ paddingLeft: Math.min(node.depth, 8) * 12 }}
                className="flex items-center rounded-md data-[state=selected]:bg-secondary data-[state=selected]:shadow-[inset_2px_0_var(--primary)]"
              >
                {hasChildren ? (
                  <Button
                    size="icon-sm"
                    variant="ghost"
                    aria-label={`${collapsed.has(node.id) ? "Expand" : "Collapse"} ${node.name}`}
                    aria-expanded={!collapsed.has(node.id)}
                    onClick={() => toggle(node.id)}
                  >
                    {collapsed.has(node.id) ? (
                      <ChevronRight size={12} />
                    ) : (
                      <ChevronDown size={12} />
                    )}
                  </Button>
                ) : (
                  <span className="inspector-spacer w-7 shrink-0" />
                )}
                <Button
                  variant="ghost"
                  size="sm"
                  className="inspector-node min-w-0 flex-1 justify-start [&>span]:truncate"
                  disabled={!node.mesh}
                  aria-pressed={node.mesh ? selectedMesh === node.id : undefined}
                  onClick={() => onSelectMesh(node.id)}
                >
                  {node.mesh ? <Box size={13} /> : <Layers size={13} />}
                  <span>{node.name}</span>
                  <small className="ml-auto rounded-sm bg-muted px-1 text-xs text-muted-foreground">
                    {node.mesh ? "Mesh" : node.type}
                  </small>
                </Button>
              </li>
            );
          })}
        </ul>
        {visible.length > limit && (
          <Button
            variant="outline"
            size="sm"
            onClick={() => setPage({ nodes: inspection.nodes, query, limit: limit + 200 })}
          >
            Show {Math.min(200, visible.length - limit)} more objects
          </Button>
        )}
        {visible.length === 0 && (
          <div className="inspector-empty px-3.5 py-[18px] text-muted-foreground">
            No objects match “{query}”.
          </div>
        )}
        <footer className="inspector-selection m-0 flex items-center gap-[9px] border-t bg-secondary/30 px-3.5 py-[11px] @max-[680px]/viewer:px-3 @max-[680px]/viewer:py-2">
          <Crosshair size={15} />
          <div className="grid min-w-0 flex-1 gap-0.5">
            <span className="text-[9px] text-muted-foreground">
              {selected ? "Selected object" : "Nothing selected"}
            </span>
            <strong className="truncate text-[10px] font-[550]">
              {selected?.name ?? "Choose a mesh to inspect"}
            </strong>
          </div>
          {selected && (
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label="Clear selection"
              onClick={() => onSelectMesh(null)}
            >
              <X size={14} />
            </Button>
          )}
        </footer>
      </aside>
    </TooltipProvider>
  );
}

import type { Material, Mesh, Object3D, SkinnedMesh, Texture } from "three";

type Resource = { dispose: () => void };
const users = new WeakMap<Resource, number>();
const cacheUsers = new Map<string, number>();

/** Keep a shared loader entry until its last viewer leaves, including Strict Mode remounts. */
export function retainModelCache(src: string, clear: () => void) {
  cacheUsers.set(src, (cacheUsers.get(src) ?? 0) + 1);
  let released = false;
  return () => {
    if (released) return;
    released = true;
    cacheUsers.set(src, cacheUsers.get(src)! - 1);
    queueMicrotask(() => {
      if (cacheUsers.get(src) !== 0) return;
      cacheUsers.delete(src);
      clear();
    });
  };
}

/** Release GPU allocations after the last mounted clone stops using them.
 * Cached Three objects and image sources remain reusable on a later mount.
 */
export function retainModelResources(model: Object3D) {
  const resources = new Set<Resource>();
  function materialResources(material: Material) {
    resources.add(material);
    for (const value of Object.values(material)) {
      if ((value as Texture | null)?.isTexture) resources.add(value as Texture);
    }
  }
  model.traverse((object) => {
    const mesh = object as Mesh;
    if (!mesh.isMesh) return;
    resources.add(mesh.geometry);
    for (const material of Array.isArray(mesh.material) ? mesh.material : [mesh.material])
      materialResources(material);
    const skinned = object as SkinnedMesh;
    if (skinned.isSkinnedMesh) resources.add(skinned.skeleton);
  });
  for (const resource of resources) users.set(resource, (users.get(resource) ?? 0) + 1);
  let released = false;
  return () => {
    if (released) return;
    released = true;
    for (const resource of resources) users.set(resource, users.get(resource)! - 1);
    // React Strict Mode and mode changes can release and acquire in one commit.
    // Wait for all mounts before deciding whether shared resources are unused.
    queueMicrotask(() => {
      for (const resource of resources) {
        if (users.get(resource) !== 0) continue;
        users.delete(resource);
        resource.dispose();
      }
    });
  };
}

import type { ViewerCameraOptions, ViewerCameraState } from "./model-viewer-types";

/** Mutable camera data lives outside React's root render loop. */
export function createViewerCameraStore() {
  let snapshot: ViewerCameraState | null = null;
  let controller: ((view: ViewerCameraState, transition: boolean) => void) | null = null;
  const listeners = new Set<() => void>();
  const getSnapshot = () => snapshot;
  const subscribe = (listener: () => void) => {
    listeners.add(listener);
    return () => {
      listeners.delete(listener);
    };
  };
  const publish = (view: ViewerCameraState | null) => {
    const current = snapshot;
    if (
      view &&
      current &&
      view.position.every((n, i) => Math.abs(n - current.position[i]) < 1e-6) &&
      view.target.every((n, i) => Math.abs(n - current.target[i]) < 1e-6)
    )
      return;
    if (!view && !snapshot) return;
    snapshot = view;
    listeners.forEach((listener) => listener());
  };
  const register = (next: typeof controller) => {
    controller = next;
    if (!next) publish(null);
  };
  const setView = (view: ViewerCameraState, options?: ViewerCameraOptions) => {
    if (!controller || !validCameraView(view)) return false;
    controller(view, options?.transition ?? true);
    return true;
  };
  return { getSnapshot, subscribe, publish, register, setView };
}

export type ViewerCameraStore = ReturnType<typeof createViewerCameraStore>;

function validCameraView(view: ViewerCameraState) {
  const values = [...view.position, ...view.target];
  return (
    values.every(Number.isFinite) &&
    view.position.some((n, i) => Math.abs(n - view.target[i]) > 1e-9)
  );
}

import type { ViewerLighting } from "./model-viewer-types";

export function viewerBackgroundColor(lighting: ViewerLighting) {
  if (lighting === "night") return "#17243a";
  if (lighting === "outside") return "#dbe9ee";
  return "#f5f5f5";
}

"use client";
import { createContext, useContext, useSyncExternalStore } from "react";
import type { ModelViewerState } from "./model-viewer-types";
import type { useModelViewerRuntime } from "./use-model-viewer-runtime";

/** Internal renderer context. Not part of the public barrel. */
export const ModelViewerContext = createContext<ReturnType<typeof useModelViewerRuntime> | null>(
  null,
);

export function useOptionalViewerRuntime() {
  return useContext(ModelViewerContext);
}

export function useViewerRuntime() {
  const context = useOptionalViewerRuntime();
  if (!context)
    throw new Error("Model viewer parts must be used inside <ModelViewerRoot> or <ModelViewer>.");
  return context;
}

/** State and actions scoped to the nearest viewer. */
export function useModelViewer(): ModelViewerState {
  return useViewerRuntime().state;
}

/** Live primary orbit camera view without rerendering the whole viewer. */
export function useModelViewerCamera() {
  const { cameraStore } = useViewerRuntime();
  return useSyncExternalStore(cameraStore.subscribe, cameraStore.getSnapshot, () => null);
}

"use client";
import { Maximize2, Minimize2 } from "lucide-react";
import type { ComponentProps } from "react";
import { cn } from "@/lib/utils";
import { useModelViewer, useViewerRuntime } from "./model-viewer-context";
import { ViewerControlButton } from "./viewer-ui";

export function ModelViewerStatus({ className, children, ...props }: ComponentProps<"div">) {
  const { state: viewer, pointerLockAvailable, locked } = useViewerRuntime();
  const instructions =
    viewer.mode === "firstPerson"
      ? pointerLockAvailable
        ? locked
          ? "WASD to fly · Space up · Shift down · Esc to release"
          : "Click the scene to look · WASD to fly"
        : "Drag to look · WASD to fly · Space / Shift vertically"
      : viewer.mode === "split"
        ? "Fixed views · Drag to pan · Scroll to zoom"
        : "Drag to orbit · Scroll to zoom";
  return (
    <div
      data-slot="model-viewer-status"
      className={cn(
        "viewer-help rounded-md border bg-popover px-2.5 py-1.5 text-xs text-popover-foreground",
        viewer.feedback?.error && "text-destructive",
        className,
      )}
      role={viewer.feedback?.error ? "alert" : "status"}
      {...props}
    >
      {children ?? viewer.feedback?.message ?? instructions}
    </div>
  );
}

export function ModelViewerFullscreen({
  className,
  children,
  onClick,
  ...props
}: ComponentProps<typeof ViewerControlButton>) {
  const viewer = useModelViewer();
  return (
    <ViewerControlButton
      data-slot="model-viewer-fullscreen"
      size="icon-sm"
      variant="secondary"
      className={cn("viewer-fullscreen", className)}
      aria-label={viewer.fullscreen ? "Exit fullscreen" : "Enter fullscreen"}
