import { useGizmoContext } from "@react-three/drei";
import { useThree } from "@react-three/fiber";
import { type PointerEvent, useEffect, useMemo, useState } from "react";
import { CanvasTexture, Vector3 } from "three";

const axes = [
  { color: "#ff4967", position: [1, 0, 0] as const, rotation: [0, 0, 0] as const },
  { color: "#7ee052", position: [0, 1, 0] as const, rotation: [0, 0, Math.PI / 2] as const },
  { color: "#4a83ff", position: [0, 0, 1] as const, rotation: [0, -Math.PI / 2, 0] as const },
] as const;

export function ViewHelper() {
  return (
    <group scale={40}>
      {axes.map((axis) => (
        <group key={axis.color} rotation={axis.rotation}>
          <mesh position={[0.4, 0, 0]}>
            <boxGeometry args={[0.8, 0.04, 0.04]} />
            <meshBasicMaterial color={axis.color} toneMapped={false} />
          </mesh>
        </group>
      ))}
      {axes.map((axis) => (
        <AxisPoint key={`positive-${axis.color}`} color={axis.color} position={axis.position} />
      ))}
      {axes.map((axis) => (
        <AxisPoint
          key={`negative-${axis.color}`}
          color="#252525"
          opacity={0.25}
          position={axis.position.map((value) => -value) as [number, number, number]}
        />
      ))}
    </group>
  );
}

function AxisPoint({
  color,
  opacity = 1,
  position,
}: {
  color: string;
  opacity?: number;
  position: readonly [number, number, number];
}) {
  const gl = useThree((state) => state.gl);
  const { tweenCamera } = useGizmoContext();
  const [hovered, setHovered] = useState(false);
  const texture = useMemo(() => {
    const canvas = document.createElement("canvas");
    canvas.width = 64;
    canvas.height = 64;
    const context = canvas.getContext("2d");
    context?.beginPath();
    context?.arc(32, 32, 18, 0, Math.PI * 2);
    if (context) context.fillStyle = color;
    context?.fill();
    const result = new CanvasTexture(canvas);
    result.anisotropy = gl.capabilities.getMaxAnisotropy() || 1;
    return result;
  }, [color, gl]);

  useEffect(() => () => texture.dispose(), [texture]);

  function activate(event: PointerEvent) {
    event.stopPropagation();
    tweenCamera(new Vector3(...position));
  }

  return (
    <sprite
      position={position}
      scale={hovered ? 1.05 : 0.82}
      onPointerDown={activate}
      onPointerOver={(event) => {
        event.stopPropagation();
        setHovered(true);
      }}
      onPointerOut={(event) => {
        event.stopPropagation();
        setHovered(false);
      }}
    >
      <spriteMaterial
        map={texture}
        alphaTest={0.15}
        opacity={opacity}
        transparent
        toneMapped={false}
      />
    </sprite>
  );
}

"use client";

import { LoaderCircle } from "lucide-react";
import { useLayoutEffect, useRef } from "react";

/** Keeps the indeterminate loader's phase stable when one loading view replaces another. */
export function ViewerLoaderSpinner() {
  const spinner = useRef<SVGSVGElement>(null);

  useLayoutEffect(() => {
    const animation = spinner.current?.getAnimations()[0];
    if (animation) animation.startTime = 0;
  }, []);

  return <LoaderCircle ref={spinner} className="viewer-loader-spinner" aria-hidden="true" />;
}

"use client";

// Shared by the scene and the lazy entry: no Three/R3F runtime imports.
import { cn } from "@/lib/utils";
import type { ModelViewerProps } from "./model-viewer-types";
import { ViewerLoaderSpinner } from "./viewer-loader-spinner";

export function ViewerLoader({
  fallback,
  poster,
  showFileName,
  src,
}: {
  fallback?: ModelViewerProps["loadingFallback"];
  poster: boolean;
  showFileName: boolean;
  src?: string;
}) {
  // Drei's useProgress observes the global loading manager, which also tracks
  // assets belonging to other viewer instances. This is intentionally
  // indeterminate until this viewer's own scene reports ready or error.
  const data = { active: true, progress: 0, item: src ?? "", loaded: 0, total: 0 };
  const custom = typeof fallback === "function" ? fallback(data) : fallback;
  if (fallback !== undefined && custom == null) return null;
  return (
    <div className={cn("viewer-loader", poster && "has-poster")} role="status" aria-live="polite">
      {fallback !== undefined ? (
        custom
      ) : (
        <>
          <ViewerLoaderSpinner />
          <span>Loading model…</span>
          {showFileName && src && <small>{fileName(src)}</small>}
        </>
      )}
    </div>
  );
}

function fileName(path: string) {
  return path.split(/[?#]/)[0].split(/[\\/]/).pop() || "Model asset";
}

"use client";

// Own the portal so installed viewers do not require modified host primitives.
import { Menu as MenuPrimitive } from "@base-ui/react/menu";
import { Tooltip as TooltipPrimitive } from "@base-ui/react/tooltip";
import { cn } from "@/lib/utils";
import { useOptionalViewerRuntime } from "./model-viewer-context";

export function DropdownMenuContent({
  align = "start",
  alignOffset = 0,
  side = "bottom",
  sideOffset = 4,
  className,
  ...props
}: MenuPrimitive.Popup.Props &
  Pick<MenuPrimitive.Positioner.Props, "align" | "alignOffset" | "side" | "sideOffset">) {
  const runtime = useOptionalViewerRuntime();
  const container =
    runtime?.state.fullscreen && !runtime.root.isExpanded ? runtime.viewerRef : undefined;
  return (
    <MenuPrimitive.Portal container={container}>
      <MenuPrimitive.Positioner
        className="isolate z-50 outline-none"
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
      >
        <MenuPrimitive.Popup
          data-slot="dropdown-menu-content"
          className={cn(
            "cn-menu-target cn-menu-translucent z-50 max-h-(--available-height) w-(--anchor-width) min-w-32 origin-(--transform-origin) overflow-x-hidden overflow-y-auto rounded-lg bg-popover p-1 text-popover-foreground shadow-md ring-1 ring-foreground/10 duration-100 outline-none data-[side=bottom]:slide-in-from-top-2 data-[side=inline-end]:slide-in-from-left-2 data-[side=inline-start]:slide-in-from-right-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-closed:animate-out data-closed:overflow-hidden data-closed:fade-out-0 data-closed:zoom-out-95",
            className,
          )}
          {...props}
        />
      </MenuPrimitive.Positioner>
    </MenuPrimitive.Portal>
  );
}

